# Evidence/report finalization only: no additional runtime functionality or job invocation.
#requires -Version 7.4
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$Root='D:\WHAT-LIES-BTWN-PRODUCTION-OS'
$Stage=Join-Path $Root 'tests\stage03d1'
$Evidence=Join-Path $Stage 'evidence'
function Write-NewText([string]$Path,[string]$Text){
    if(-not $Path.StartsWith($Root+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Write outside Production OS'}
    $bytes=[Text.UTF8Encoding]::new($false).GetBytes($Text)
    $stream=[IO.File]::Open($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
    try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}
}
function Save-Json([string]$Path,$Value){Write-NewText $Path (ConvertTo-Json -InputObject $Value -Depth 100)}
function Hash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Load-Json([string]$Path){return ,(Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -AsHashtable -NoEnumerate)}
function Json-Text($Value){ConvertTo-Json -InputObject $Value -Depth 100 -Compress}
$before=Load-Json (Join-Path $Evidence 'all-existing-before.json')
$results=Load-Json (Join-Path $Evidence 'run2\test-results.json')
$closure=Load-Json (Join-Path $Evidence 'run2\seven-distinct-closure.json')
$adaptations=Load-Json (Join-Path $Evidence 'run2\composite-adaptations.json')
if(@($results | Where-Object {$_.status -eq 'FAIL'}).Count){throw 'A regression check failed; no successful receipt'}
if($closure.Count -ne 7 -or @($closure | Where-Object {$_.status -ne 'PASS'}).Count){throw 'Seven distinct failures not closed'}
$allowed=@('core\Wlb.Common.ps1','core\Test-WlbManifest.ps1','policy\runtime-lock.json','manifests\draft\POC0-CALIBRATION-001.json')
$reasons=@{
    'core\Wlb.Common.ps1'='Untyped value boundaries; integer/boolean/string/array/object/null contracts; exact required keys; canonical graph/link; full policy shape/type contract; preserve JSON root container without pipeline unwrapping.'
    'core\Test-WlbManifest.ps1'='Invoke strict policy/graph contracts; require integer manifest budget scalars; retain all existing binding/path/state/value checks and unconditional ExecutionEligibility refusal.'
    'policy\runtime-lock.json'='Replace only prepared_artifacts SHA-256 values for the two changed PowerShell files; no new runtime identity or gate claim.'
    'manifests\draft\POC0-CALIBRATION-001.json'='Replace only binding.runtime_lock_sha256; all DRAFT/nonapproval/graph/parameter/budget/owner/provenance values preserved.'
}
$preservation=@(foreach($entry in $before){
    $path=Join-Path $Root $entry.path
    $item=Get-Item -LiteralPath $path -Force
    $oldTime=if($entry.last_write_utc -is [datetime]){$entry.last_write_utc.ToUniversalTime().ToString('o')}else{[string]$entry.last_write_utc}
    $currentHash=Hash $path
    [ordered]@{path=$entry.path;before_bytes=$entry.bytes;after_bytes=$item.Length;before_sha256=$entry.sha256;after_sha256=$currentHash;bytes_and_hash_unchanged=($entry.bytes -eq $item.Length -and $entry.sha256 -ceq $currentHash);last_write_unchanged=($oldTime -ceq $item.LastWriteTimeUtc.ToString('o'));authorized_change=($entry.path -in $allowed)}
})
$changed=@($preservation | Where-Object {-not $_.bytes_and_hash_unchanged})
if($changed.Count -ne 4 -or @($changed | Where-Object {-not $_.authorized_change}).Count){throw 'Unexpected preexisting-file changeset'}
if(@($preservation | Where-Object {-not $_.authorized_change -and -not $_.last_write_unchanged}).Count){throw 'Unlisted preexisting write-time change'}
Save-Json (Join-Path $Evidence 'all-existing-after-comparison.json') $preservation
$changeset=@(foreach($entry in $changed){[pscustomobject]@{absolute_path=Join-Path $Root $entry.path;relative_path=$entry.path;before_bytes=$entry.before_bytes;after_bytes=$entry.after_bytes;before_sha256=$entry.before_sha256;after_sha256=$entry.after_sha256;reason=$reasons[$entry.path]}})
Save-Json (Join-Path $Evidence 'EXACT_CHANGESET.json') $changeset
Write-NewText (Join-Path $Evidence 'EXACT_CHANGESET.csv') (($changeset | ConvertTo-Csv -NoTypeInformation) -join "`n")
# Prove that JSON edits are only the specified SHA-256 bindings.
