foreach($key in $oldLock.prepared_artifacts.Keys){$lockComparison.prepared_artifacts[$key]=$oldLock.prepared_artifacts[$key]}
if((Json-Text $oldLock) -cne (Json-Text $lockComparison)){throw 'Runtime metadata changed beyond authorized bindings'}
$bindingChanges=@(foreach($key in $oldLock.prepared_artifacts.Keys){if($oldLock.prepared_artifacts[$key] -cne $newLock.prepared_artifacts[$key]){[ordered]@{path=$key;before=$oldLock.prepared_artifacts[$key];after=$newLock.prepared_artifacts[$key]}}})
if($bindingChanges.Count -ne 2 -or @($bindingChanges | Where-Object {$_.path -notin @('core\Wlb.Common.ps1','core\Test-WlbManifest.ps1')}).Count){throw 'Unexpected artifact binding delta'}
foreach($key in $newLock.prepared_artifacts.Keys){if((Hash (Join-Path $Root $key)) -cne $newLock.prepared_artifacts[$key]){throw ('Binding mismatch: '+$key)}}
$oldManifest=Load-Json (Join-Path $Stage 'baseline\manifests\draft\POC0-CALIBRATION-001.json')
