if((Json-Text $oldManifest) -cne (Json-Text $manifestComparison)){throw 'Manifest changed beyond runtime hash reference'}
if($manifest.binding.runtime_lock_sha256 -cne (Hash (Join-Path $Root 'policy\runtime-lock.json'))){throw 'Manifest runtime binding mismatch'}
