if($policy.execution_enabled -ne $false -or $manifest.state -cne 'DRAFT' -or $manifest.approval_contract.record_created -ne $false){throw 'Execution gate changed'}
$namespaces=@(foreach($relative in @('approvals','jobs','workflows\approved','runtimes')){[ordered]@{path=Join-Path $Root $relative;exists=Test-Path -LiteralPath (Join-Path $Root $relative)}})
if(@($namespaces | Where-Object {$_.exists}).Count){throw 'Unexpected real execution namespace'}
$baselineChecks=@(foreach($relative in @('core\Invoke-WlbJob.ps1','core\Test-WlbManifest.ps1','core\Test-WlbOutput.ps1','core\Wlb.Common.ps1','policy\shot-manifest.schema.json','policy\executor-policy.json','policy\runtime-lock.json','workflows\draft\poc0-calibration.api.json','manifests\draft\POC0-CALIBRATION-001.json','bible\character-bible.v0.1.json','README.md','spec\FUTURE_EXECUTION_CONTRACT.md','STAGE03B_PREP_RECEIPT.md')){
    $snapshot=Join-Path (Join-Path $Stage 'baseline') $relative
    $expected=@($before | Where-Object {$_.path -ceq $relative})[0]
    [ordered]@{original_path=$relative;snapshot=$snapshot;snapshot_sha256=Hash $snapshot;expected_before_sha256=$expected.sha256;matches=((Hash $snapshot) -ceq $expected.sha256)}
})
