Save-Json (Join-Path $Evidence 'closed-gates-final.json') ([ordered]@{namespaces=$namespaces;execution_enabled=$policy.execution_enabled;state=$manifest.state;approval_record_created=$manifest.approval_contract.record_created;launcher_hash_unchanged=(@($preservation | Where-Object {$_.path -ceq 'core\Invoke-WlbJob.ps1'})[0].bytes_and_hash_unchanged);runtime_started=$false;network_invoked=$false;gpu_job=$false})
