$diff=@('# Stage03D1 source/binding diff evidence','','Original bytes are retained under tests\stage03d1\baseline. Lines with <= are old-only; => are current-only. This is read-only Compare-Object evidence, not a Git operation.','')
foreach($entry in $changeset){$diff+='## '+$entry.relative_path;$diff+='';$diff+='```text';$diff+=@(Compare-Object -ReferenceObject (Get-Content -LiteralPath (Join-Path (Join-Path $Stage 'baseline') $entry.relative_path)) -DifferenceObject (Get-Content -LiteralPath (Join-Path $Root $entry.relative_path)) | ForEach-Object {$_.SideIndicator+' '+$_.InputObject});$diff+='```';$diff+=''}
